"""The ``run.yaml`` template used by ``pdb-md md init``.

The template is a :class:`string.Template` so that a single source of truth can
serve both ``--template`` (with the defaults) and the interactive wizard (with
the user's answers).  Only ``$`` is special to :class:`string.Template`; the
AMBER ``addAtomTypes`` curly braces therefore pass through untouched.
"""

from __future__ import annotations

import string
from pathlib import Path

from .errors import ConfigError

TEMPLATE = string.Template(
    """\
# run.yaml - generated by `pdb-md md init`. All relative paths are resolved
# against the directory containing this file, not the caller's CWD.
schema_version: 1
run_name: $run_name
workdir: .                     # relative to run.yaml dir

tools:
  gmx: $gmx
  tleap: $tleap
  parmed_python: $parmed_python
  timeout_minutes: 0           # 0 = no timeout (production MD can take long)

input:
  structure: $structure
  preprocess:
    enabled: false
    steps: []                  # e.g. ["pdb-md","select","-I","{in}","-O","{out}","-S","A:1-308"]

system:
  solvate:
    box: TIP3PBOX              # passed to tleap solvateBox
    buffer_angstrom: 10.0
  salt:
    concentration_M: $salt_concentration
    cation: $cation
    anion: $anion
    water_count: null          # explicit override if leap.log parsing fails
    net_charge: null           # same
  species:                     # used for group definitions; classified by resname
    metal_resnames: [ZN, ZN3, ZN4]
    dna_resnames: [DA, DC, DG, DT, DA5, DC5, DG5, DT5, DA3, DC3, DG3, DT3]
    solvent_resnames: [WAT, SOL, HOH, NA, CL]

forcefield:
  protein: leaprc.protein.ff14SB
  nucleic: leaprc.DNA.bsc1
  water: leaprc.water.tip3p
  ions_frcmod: frcmod.ions1lm_126_tip3p
  zaff_prep: params/ZAFF.prep
  zaff_frcmod: params/ZAFF.frcmod
  atom_types: |
    addAtomTypes { { "ZN" "Zn" "sp3" } { "S4" "S" "sp3" } { "N3" "N" "sp3" } }

zinc_sites:
  # Ligand count/kind is yours to define; ZAFF requires four-coordinate Zn.
  # The site below is a C2H2 (center ID 4) example; rewrite resname/atom for
  # C3H/C4/CCCH etc. following your center table.
  - center_id: 4               # optional; records the site and runs taboo checks
    coordination_number: 4     # ZAFF only supports 4
    zn: {chain: B, resid: 365, resname: ZN4, atom: ZN}
    ligands:
      - {chain: A, resid: 62, resname: CY4, atom: SG}
      - {chain: A, resid: 65, resname: CY4, atom: SG}
      - {chain: A, resid: 78, resname: HD2, atom: NE2}
      - {chain: A, resid: 82, resname: HD2, atom: NE2}

coordination_check:
  bond_min_angstrom: 1.8
  bond_max_angstrom: 2.6
  on_violation: fail           # fail | warn; coordinating atoms are never replaced
  report_extra_near_atoms: true  # report unlisted SG/NE2/ND1/SD/O within range

mdp:
  em: [$em1_mdp, $em2_mdp]     # run in order
  nvt: $nvt_mdp
  npt: $npt_mdp
  prod: $prod_mdp

grompp:
  maxwarn: 0                   # can be overridden per stage

replicates:
  count: $replicates
  seeds: [$seeds]              # only replaces NVT mdp gen_seed

mdrun:
  args: ["-nb", "gpu", "-pme", "gpu", "-bonded", "gpu", "-update", "gpu", "-v"]
  ntomp: null

pbc:
  enabled: true
  ndx: auto                    # auto = generate from conf.gro; or an existing analysis.ndx
  steps: [whole, cluster, whole, nojump, center]
  groups:
    cluster: Complex
    center: Complex
    output: System
  bond_max_angstrom: 3.0       # warns on Zn-ligand distance after correction

topology:
  posre_fc: 1000.0
"""
)


_DEFAULT_VALUES = {
    "run_name": "myrun",
    "structure": "inputs/structure.pdb",
    "gmx": "gmx",
    "tleap": "tleap",
    "parmed_python": "python",
    "em1_mdp": "mdp/em1.mdp",
    "em2_mdp": "mdp/em2.mdp",
    "nvt_mdp": "mdp/nvt.mdp",
    "npt_mdp": "mdp/npt.mdp",
    "prod_mdp": "mdp/md.mdp",
    "replicates": "3",
    "seeds": "10001, 20002, 30003",
    "salt_concentration": "0.15",
    "cation": "NA",
    "anion": "CL",
}


def render_template(values: dict[str, str]) -> str:
    """Return the template with every ``$`` placeholder substituted."""

    return TEMPLATE.substitute(values)


def write_config(output: Path, values: dict[str, str], force: bool) -> None:
    """Write the rendered template to ``output``.

    Refuses to clobber an existing file unless ``force`` is true; creates the
    parent directory when needed.
    """

    output = Path(output)
    if output.exists() and not force:
        raise ConfigError(
            "refusing to overwrite existing file: {}".format(output),
            hint="pass --force to overwrite",
        )
    output.parent.mkdir(parents=True, exist_ok=True)
    output.write_text(render_template(values))
